recipes.code:
{
  "inputs": [
    {
      "id": "quackr-api-key",
      "type": "promptString",
      "description": "Your Quackr API key, from your profile page at quackr.io",
      "password": true
    }
  ],
  "servers": {
    "quackr": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "quackr-mcp@1.0.1"
      ],
      "env": {
        "QUACKR_API_KEY": "${input:quackr-api-key}"
      }
    }
  }
}
